package com.earthtrip.wallet.adapter.in.web.api.v1.trips.by_trip_id.reservations.by_reservation_id.refund_receipts;import com.earthtrip.sharedkernel.security.CurrentActor;import com.earthtrip.wallet.application.port.in.WalletRecordUseCase;import jakarta.validation.Valid;import jakarta.validation.constraints.NotNull;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/trips/{tripId}/reservations/{reservationId}/refund-receipts") class RefundReceiptsController{private final WalletRecordUseCase useCase;private final CurrentActor actor;RefundReceiptsController(WalletRecordUseCase u,CurrentActor a){useCase=u;actor=a;}@PostMapping @ResponseStatus(HttpStatus.CREATED) WalletRecordUseCase.RecordResult post(@PathVariable UUID tripId,@PathVariable UUID reservationId,@Valid @RequestBody RefundMutation r){useCase.get(tripId,actor.requireUserId(),"RESERVATION",reservationId);return useCase.create(tripId,actor.requireUserId(),"REFUND_RECEIPT",false,new WalletRecordUseCase.Command(r.requestId(),reservationId,r.payload(),"RECEIVED",r.visibility(),0,0));}}
record RefundMutation(@NotNull UUID requestId,@NotNull Map<String,Object> payload,String visibility){}
